-- Chạy SAU schema.sql trong cong_doan_portal.
-- CHÚ Ý: card_number không import từ Excel, luôn NULL khi tạo tài khoản mới.
-- Mật khẩu đầu tiên = ddmmyyyy của DOB, lưu bằng bcrypt password_hash(PASSWORD_BCRYPT).
-- Tài khoản thiếu DOB có pass_hash=NULL, chưa đăng nhập được.
-- Dữ liệu nhạy cảm: hạn chế người truy cập bản SQL và không public trên website.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS student_profile_details (
 user_id INT NOT NULL PRIMARY KEY,
 gender ENUM('Nam','Nữ') DEFAULT NULL,
 hometown VARCHAR(191) NULL,
 ethnicity VARCHAR(120) NULL,
 religion VARCHAR(120) NULL,
 youth_book_status VARCHAR(100) NULL,
 party_membership VARCHAR(120) NULL,
 party_joined_date DATE NULL,
 CONSTRAINT fk_student_profile_details_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


COMMIT;
